export type BackupTextKey = keyof typeof messages;
const language = (column: number) => Object.fromEntries(Object.entries(messages).map(([key, values]) => [key, values[column]])) as Record<BackupTextKey, string>;
export const systemBackupTranslations: Record<Locale, Record<BackupTextKey, string>> = {
  zh: language(0), en: language(1), ja: language(2), ko: language(3), de: language(4),
};
export const backupLocaleTags: Record<Locale, string> = { zh: 'zh-CN', en: 'en-US', ja: 'ja-JP', ko: 'ko-KR', de: 'de-DE' };
export function formatBackupDate(value: string, locale: Locale): string {
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return '—';
  return new Intl.DateTimeFormat(backupLocaleTags[locale], {
    year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', timeZoneName: 'short',
  }).format(date);
}
